<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= html_escape($title); ?></title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.34.1/dist/tabler-icons.min.css"><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root{--ink:#17233d;--muted:#68738a;--line:#e6ebf3}*{box-sizing:border-box}body{margin:0;font-family:'Plus Jakarta Sans',sans-serif;color:var(--ink);background:radial-gradient(circle at 8% 8%,#dbeafe 0,transparent 28%),radial-gradient(circle at 92% 90%,#ede9fe 0,transparent 30%),#f5f7fb;min-height:100vh}.shell{width:min(980px,calc(100% - 28px));margin:auto;padding:34px 0}.result{background:#fff;border-radius:28px;box-shadow:0 24px 70px rgba(31,41,55,.13);overflow:hidden}.hero{display:grid;grid-template-columns:1.3fr .7fr;gap:25px;padding:38px 42px;background:linear-gradient(135deg,#fff,#f8fbff);border-bottom:1px solid var(--line)}.eyebrow{display:inline-flex;gap:7px;align-items:center;padding:7px 12px;border-radius:99px;background:#eef4ff;color:#1d4ed8;font-size:.75rem;font-weight:800;text-transform:uppercase}.hero h1{margin:18px 0 8px;font-size:clamp(1.6rem,4vw,2.35rem)}.subtitle{color:var(--muted);margin:0}.person{display:flex;align-items:center;gap:10px;margin-top:22px;font-weight:700}.avatar-soft{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;background:#e0e7ff;color:#4338ca}.score-box{display:flex;align-items:center;justify-content:center}.score{width:180px;height:180px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;box-shadow:0 16px 35px #0002,inset 0 0 0 9px #ffffff29}.passed{background:linear-gradient(145deg,#16a34a,#22c55e)}.failed{background:linear-gradient(145deg,#dc2626,#f97316)}.pending{background:linear-gradient(145deg,#d97706,#f59e0b)}.pct{font-size:3rem;font-weight:800;line-height:1}.content{padding:30px 42px 36px}.heading{font-size:.8rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:800;margin:0 0 14px}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.stat{border:1px solid var(--line);border-radius:16px;padding:16px 8px;text-align:center}.stat b{display:block;font-size:1.65rem}.stat small{display:block;color:var(--muted);font-size:.7rem;margin-top:5px}.total b{color:#2563eb}.answered b{color:#7c3aed}.correct b{color:#16a34a}.wrong b{color:#dc2626}.empty b{color:#64748b}.pending-stat b{color:#d97706}.details{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:22px}.detail{padding:15px 17px;background:#f8fafc;border-radius:14px}.detail span{display:block;color:var(--muted);font-size:.73rem;margin-bottom:4px}.flag{margin-top:18px;padding:12px 15px;border-radius:12px;background:#fff1f2;color:#be123c}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:28px;padding-top:24px;border-top:1px solid var(--line)}.actions .btn{border-radius:11px;font-weight:700}.hidden{padding:65px 30px;text-align:center}@media(max-width:760px){.shell{padding:14px 0}.result{border-radius:20px}.hero{grid-template-columns:1fr;padding:25px 20px;text-align:center}.score-box{grid-row:1}.score{width:150px;height:150px}.pct{font-size:2.4rem}.person{justify-content:center}.content{padding:24px 18px}.stats{grid-template-columns:repeat(3,1fr)}.details{grid-template-columns:1fr}.actions .btn{flex:1 1 145px}}
</style></head><body>
<?php $pct=(float)($attempt['percentage']??0);$passed=$attempt['is_passed'];$class=$passed===null?'pending':($passed?'passed':'failed');$headline=$passed===null?'Jawaban sedang dinilai':($passed?'Kerja bagus, kamu lulus!':'Tetap semangat, coba lagi!');$status=$passed===null?'Menunggu penilaian essay':($passed?'Lulus':'Belum lulus');$seconds=(int)($attempt['time_spent_seconds']??0);$duration=$seconds?sprintf('%02d:%02d:%02d',intdiv($seconds,3600),intdiv($seconds%3600,60),$seconds%60):'—'; ?>
<main class="shell"><section class="result"><?php if(!$hidden): ?><div class="hero"><div><span class="eyebrow"><i class="ti ti-clipboard-check"></i> Hasil Latihan</span><h1><?= html_escape($headline); ?></h1><p class="subtitle"><?= html_escape($attempt['session_title']); ?></p><div class="person"><span class="avatar-soft"><i class="ti ti-user"></i></span><?= html_escape($attempt['full_name']); ?></div></div><div class="score-box"><div class="score <?= $class; ?>"><div class="pct"><?= number_format($pct,1); ?>%</div><small>Nilai Akhir</small></div></div></div>
<div class="content"><h2 class="heading">Rincian Pengerjaan</h2><div class="stats"><div class="stat total"><b><?= (int)$summary['total']; ?></b><small>Total Soal</small></div><div class="stat answered"><b><?= (int)$summary['answered']; ?></b><small>Dikerjakan</small></div><div class="stat correct"><b><?= (int)$summary['correct']; ?></b><small>Benar</small></div><div class="stat wrong"><b><?= (int)$summary['wrong']; ?></b><small>Salah</small></div><div class="stat empty"><b><?= (int)$summary['unanswered']; ?></b><small>Tidak Dikerjakan</small></div><div class="stat pending-stat"><b><?= (int)$summary['pending']; ?></b><small>Belum Dinilai</small></div></div>
<div class="details"><div class="detail"><span>Skor diperoleh</span><strong><?= number_format((float)$attempt['total_score'],1); ?> / <?= number_format((float)$attempt['max_possible_score'],1); ?> poin</strong></div><div class="detail"><span>Waktu pengerjaan</span><strong><?= $duration; ?></strong></div><div class="detail"><span>Status hasil</span><strong><?= html_escape($status); ?></strong></div></div><?php if($attempt['is_flagged']): ?><div class="flag"><i class="ti ti-alert-triangle"></i> Attempt ini ditandai sistem pengawasan.</div><?php endif; ?>
<div class="actions"><?php if($attempt['allow_review']&&in_array($attempt['status'],['submitted','timed_out'],true)): ?><a href="<?= base_url('quiz/review/'.$attempt['id']); ?>" class="btn btn-primary"><i class="ti ti-book-2"></i> Lihat Pembahasan</a><?php endif; ?><?php if($attempt['session_type']==='practice'): ?><a href="<?= base_url('quiz/practice/'.$attempt['session_code']); ?>" class="btn btn-outline-primary"><i class="ti ti-refresh"></i> Coba Lagi</a><?php endif; ?><a href="<?= base_url('belajar/raport'); ?>" class="btn btn-outline-secondary"><i class="ti ti-report"></i> Riwayat Latihan</a><a href="<?= base_url('belajar'); ?>" class="btn btn-outline-secondary"><i class="ti ti-home"></i> Arena Belajar</a></div></div>
<?php else: ?><div class="hidden"><i class="ti ti-clock-hour-4 fs-1 text-warning"></i><h1>Jawaban sudah dikumpulkan</h1><p class="text-secondary">Hasil akan ditampilkan setelah penilaian atau pengumuman dibuka.</p><a href="<?= base_url('belajar/raport'); ?>" class="btn btn-primary">Kembali ke Riwayat</a></div><?php endif; ?></section></main></body></html>
